{"content":"using System.IO;

using Microsoft.Extensions.DependencyInjection;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point, extracted from <c>Program.cs</c> so the tests can drive the exact host
/// graph the CLI runs (F-428 P12.13): same <see cref="HostedServices.AutoWrongCensusHostBuilderFactory"/>,
/// same hosted service, same exit code.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs one census/pairs invocation and returns the process exit code.</summary>
	/// <param name="args">CLI arguments: <c>census &lt;trace.jsonl&gt;</c> or <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.</param>
	/// <param name="output">TSV sink; defaults to <see cref="Console.Out"/>.</param>
	/// <param name="error">Summary/diagnostics sink; defaults to <see cref="Console.Error"/>.</param>
	/// <returns>0 on success; 1 on a missing file, an unusable set, or a malformed invocation.</returns>
	public static async Task<int> RunAsync(
		string[] args,
		TextWriter? output = null,
		TextWriter? error = null)
	{
		ArgumentNullException.ThrowIfNull(args);

		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			Options.AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = HostedServices.AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		var hostedService = host.Services.GetRequiredService<HostedServices.AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
