{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — using the production helpers only (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>, <see cref="IngredientLineResolver.ShouldReuse(string, string)"/>
/// and <see cref="IngredientLineResolver.SingularizeToken"/>.
/// <para>
/// Relation order (first that holds wins, brief §4): no-label, pack-unit-state, compound-head-lost,
/// state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food, other. A relation check
/// that needs a trace field the line lacks classifies the line <c>other</c> and names the field
/// (brief §8).
/// </para>
/// <para>
/// The key head phrase is the key description's normalized tokens up to the first token the
/// production state/modifier vocabulary marks as non-head: <see cref="FdcLexicon.ModifierWords"/> or a
/// non-<see cref="FoodState.None"/> result from <see cref="FdcMatcher.ExtractCandidateState"/> /
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> on the single token. No new lexicon is introduced.
/// </para>
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks: ExtractCandidateState/
	// ExtractCandidateSatisfiers take IReadOnlyList, and the runner is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier over the production normalizer and the exact-override key index.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The key set of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Relation: the expected label is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key row is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a needed trace field is missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Classifies one auto-wrong line. <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; never null.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrEmpty(acceptedDesc)
			? null
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = acceptedParsed is null ? [] : SingularPhrase(acceptedParsed.HeadTerm);

		var relation = ClassifyRelation(line.RawText, keyDesc, acceptedDesc, keyTier, acceptedTier, keyState, acceptedState, keyHeadPhrase, parsedNameTokens, keyHead, acceptedHead, keyParsed, acceptedParsed, out string? missingField, out IReadOnlyList<string>? keyOnlyQualifiers, out IReadOnlyList<string>? acceptedOnlyQualifiers);

		var (site, overrideKey) = ClassifySite(atom, line.RawText);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first token the
	/// production state/modifier vocabulary marks as non-head.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsNonHeadToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/> ∪
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds
	/// <c>StateAgrees</c> (FdcMatcher.cs:1155-1157).
	/// </summary>
	/// <param name="tokens">The normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse(string, string)"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>True when the production rule reuses; false when it would not.</returns>
	public static bool ProductionShouldReuse(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	private static string ClassifyRelation(
		string rawText,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHeadPhrase,
		IReadOnlyList<string> parsedNameTokens,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		ParsedFdcDescription keyParsed,
		ParsedFdcDescription? acceptedParsed,
		out string? missingField,
		out IReadOnlyList<string>? keyOnlyQualifiers,
		out IReadOnlyList<string>? acceptedOnlyQualifiers)
	{
		missingField = null;
		keyOnlyQualifiers = null;
		acceptedOnlyQualifiers = null;

		// 1. no-label.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NoLabel;
		}

		// 2. pack-unit-state: a can/jar unit in the raw line, the key row is Canned, the accepted row is not.
		if (PackUnitRegex().IsMatch(rawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
		{
			return PackUnitState;
		}

		// 3. compound-head-lost: the key head phrase has two or more words and the parsed name is only its first word.
		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		if (headsAgree)
		{
			// 4. state-mismatch: the head terms agree and the state masks differ.
			if (keyState != acceptedState)
			{
				return StateMismatch;
			}

			// 5. row-choice-tier: head and state agree and the dataset tier differs.
			if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(acceptedTier))
			{
				missingField = string.IsNullOrEmpty(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return Other;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				return RowChoiceTier;
			}

			// 6. same-head-other-qualifier: head, state and tier agree; record the qualifier difference.
			keyOnlyQualifiers = QualifierDiff(keyParsed.Qualifiers, acceptedParsed?.Qualifiers ?? []);
			acceptedOnlyQualifiers = QualifierDiff(acceptedParsed?.Qualifiers ?? [], keyParsed.Qualifiers);
			return SameHeadOtherQualifier;
		}

		// 7. sibling-food: the head terms differ.
		return SiblingFood;
	}

	private (string Site, string OverrideKey) ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return (string.Empty, string.Empty);
		}

		switch (atom.Path)
		{
			case "override":
				return (SiteOverride, _overrideKeys.Contains(NormalizeForOverrideKey(rawText)) ? "yes" : "no");
			case "curated":
				return (SiteCurated, string.Empty);
			case "ranker":
				return (atom.Reused ? SiteReuse : SiteRanker, string.Empty);
			default:
				return (string.Empty, string.Empty);
		}
	}

	private static IReadOnlyList<string> QualifierDiff(IReadOnlyList<string> left, IReadOnlyList<string> right)
	{
		var rightSet = new HashSet<string>(right, StringComparer.OrdinalIgnoreCase);
		return left.Where(t => !rightSet.Contains(t)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
	}

	private static bool IsNonHeadToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		// The single-token state/satisfier checks are the production functions themselves; the
		// "dry roasted" adjacency nuance of ExtractCandidateSatisfiers cannot apply to one token.
		return FdcMatcher.ExtractCandidateState([token]) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers([token]) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 ? values[0] : string.Empty;

	/// <summary>
	/// The production raw-key normalization for the exact-override lookup: lowercase, trimmed, cut at
	/// the first parenthesis — the same cleaning <c>FdcMatcher.MatchAsync</c> applies before
	/// <c>SpecialCases.TryGetRaw</c> (FdcMatcher.cs:165-168; <c>StripFromParenthesis</c> is private,
	/// so the cut is applied here and noted in the report).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The normalized key candidate.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var lowered = rawText.Trim().ToLowerInvariant();
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? lowered[..paren] : lowered).Trim();
	}
}
