{"content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads a HoldoutGate trace JSONL, classifies every auto-wrong line
/// (<c>auto == true &amp;&amp; correct == false</c>) through <see cref="AutoWrongClassifier"/>,
/// writes the TSV to the output sink and the relation × site summary to the error sink.
/// Refuses any trace whose record <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunnerDeps deps,
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	IAutoWrongCensusOutput output) : IAutoWrongCensusRunner
{
	private readonly IAutoWrongCensusRunnerDeps _deps = deps;
	private readonly AutoWrongCensusOptions _options = options.Value;
	private readonly AutoWrongClassifier _classifier = classifier;
	private readonly IAutoWrongCensusOutput _output = output;

	/// <summary>TSV column order for the <c>census</c> subcommand (brief §4).</summary>
	public const string CensusHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	/// <summary>TSV column order for the <c>pairs</c> subcommand.</summary>
	public const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken stoppingToken)
	{
		await Task.CompletedTask.ConfigureAwait(false);

		if (string.IsNullOrEmpty(_options.Command))
		{
			_output.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			_output.Error.WriteLine($"trace file not found: {_options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, stoppingToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !IsAllowedSet(l.Set));
		if (refused is not null)
		{
			_output.Error.WriteLine($"refused: trace record set '{refused.Set}' is not debug or batch (D-029)");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(lines);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				_output.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "<none>"}' on {line.HoldoutId}#{line.LineIndex}");
				continue;
			}

			results.Add(result);
		}

		_output.Output.WriteLine(CensusHeader);
		foreach (var r in results)
		{
			_output.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}

		WriteSummary(_options.TracePath, lines.Count, autoWrong.Count, results);

		return unknownSite > 0 ? 1 : 0;
	}

	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			_output.Error.WriteLine($"census tsv not found: {_options.CensusTsvPath}");
			return 1;
		}

		var windowRows = ReadWindowRows(_options.CensusTsvPath);
		if (windowRows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var missing = 0;

		_output.Output.WriteLine(PairsHeader);
		foreach (var row in windowRows)
		{
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missing++;
				_output.Error.WriteLine($"census row {row.HoldoutId}#{row.LineIndex} not found in trace");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', _classifier.KeyHeadPhrase(_deps.Normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_deps.Normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));

			_output.Output.WriteLine(string.Join('\t',
				Sanitize(row.HoldoutId),
				row.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(parsedNameHead),
				Sanitize(keyHead),
				Sanitize(line.RawText)));
			emitted++;
		}

		_output.Error.WriteLine($"pairs: emitted={emitted} missingInTrace={missing} from {_options.CensusTsvPath}");
		return missing > 0 ? 1 : 0;
	}

	private void WriteSummary(string tracePath, int totalLines, int autoWrongCount, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		_output.Error.WriteLine($"census: {tracePath} lines={totalLines} autoWrong={autoWrongCount} classified={results.Count} set={set}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			_output.Error.WriteLine($"relation={group.Key.Relation}\tsite={group.Key.Site}\tcount={group.Count()}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherRate = results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0;
		_output.Error.WriteLine($"other rate: {otherCount}/{results.Count} ({otherRate:0.0}%)");

		var missingFields = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key);
		if (missingFields.Any())
		{
			foreach (var group in missingFields)
			{
				_output.Error.WriteLine($"missing field {group.Key}: {group.Count()}");
			}
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			_output.Error.WriteLine($"override-site lines: {overrideLines.Count}, exact-overrides.json key hits: {overrideLines.Count(r => r.OverrideKey == "yes")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var checkedCount = 0;
			var shouldReuseFalse = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
				if (atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId))
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					shouldReuseFalse++;
				}
			}

			_output.Error.WriteLine($"reuse-site lines: {reuseLines.Count}, ShouldReuse(parsedName, linkedIngredientId) false: {shouldReuseFalse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			_output.Error.WriteLine($"row-choice-tier: {tierLines.Count}, key tier higher: {keyHigher}, accepted tier higher: {tierLines.Count - keyHigher}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			_output.Error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _summaryLines = null;

	private TraceLine? FindLine(ClassificationResult r) =>
		_summaryLines is not null && _summaryLines.HoldoutId == r.HoldoutId && _summaryLines.LineIndex == r.LineIndex
			? _summaryLines
			: null;

	private static IReadOnlyList<TraceLine>? ReadTraceAsync(string path, CancellationToken stoppingToken)
	{
		stoppingToken.ThrowIfCancellationRequested();

		var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		try
		{
			foreach (var raw in File.ReadLines(path))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, options)
					?? throw new InvalidOperationException($"trace line failed to parse: {path}"));
			}
		}
		catch (Exception ex) when (ex is IOException or JsonException or InvalidOperationException)
		{
			Console.Error.WriteLine($"failed to read trace {path}: {ex.Message}");
			return null;
		}

		return lines;
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadWindowRows(string path)
	{
		try
		{
			var all = File.ReadAllLines(path);
			if (all.Length == 0)
			{
				Console.Error.WriteLine($"census tsv is empty: {path}");
				return null;
			}

			var header = all[0].Split('\t');
			var idCol = Array.IndexOf(header, "holdoutId");
			var idxCol = Array.IndexOf(header, "lineIndex");
			var blockerCol = Array.IndexOf(header, "blocker");
			var routeCol = Array.IndexOf(header, "route");
			if (idCol < 0 || idxCol < 0 || blockerCol < 0 || routeCol < 0)
			{
				Console.Error.WriteLine($"census tsv header missing holdoutId/lineIndex/blocker/route: {path}");
				return null;
			}

			var rows = new List<(string, int)>();
			for (var i = 1; i < all.Length; i++)
			{
				var cells = all[i].Split('\t');
				if (cells.Length <= Math.Max(idCol, Math.Max(idxCol, Math.Max(blockerCol, routeCol))))
				{
					continue;
				}

				if (cells[blockerCol] == "window"
					&& (cells[routeCol] == "compound" || cells[routeCol] == "other")
					&& int.TryParse(cells[idxCol], NumberStyles.Integer, CultureInfo.InvariantCulture, out var lineIndex))
				{
					rows.Add((cells[idCol], lineIndex));
				}
			}

			return rows;
		}
		catch (Exception ex) when (ex is IOException or FormatException)
		{
			Console.Error.WriteLine($"failed to read census tsv {path}: {ex.Message}");
			return null;
		}
	}

	private static bool IsAllowedSet(string set) =>
		set.Equals("debug", StringComparison.OrdinalIgnoreCase) || set.Equals("batch", StringComparison.OrdinalIgnoreCase);

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
