{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace. TSV goes to the
/// output writer, the relation × site summary and every diagnostic to the error writer; the exit
/// code is the process contract (0 success, 1 missing input / refused set / unusable arguments).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	TextWriter output,
	TextWriter error) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] AllowedSets = ["debug", "batch"];

	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	/// <inheritdoc />
	public Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (string.IsNullOrEmpty(opts.Command))
		{
			error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return Task.FromResult(1);
		}

		if (!File.Exists(opts.TracePath))
		{
			error.WriteLine($"trace file not found: {opts.TracePath}");
			return Task.FromResult(1);
		}

		var lines = ReadTrace(opts.TracePath, out var readError);
		if (lines is null)
		{
			error.WriteLine(readError);
			return Task.FromResult(1);
		}

		var refused = lines.FirstOrDefault(l => !AllowedSets.Contains(l.Set, StringComparer.OrdinalIgnoreCase));
		if (refused is not null)
		{
			error.WriteLine($"refused: trace set '{refused.Set}' is not debug or batch (D-029: no sealed read)");
			return Task.FromResult(1);
		}

		return opts.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensusAsync(lines, cancellationToken)
			: RunPairsAsync(lines, cancellationToken);
	}

	private Task<int> RunCensusAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSites = 0;

		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				error.WriteLine(ex.Message);
				return Task.FromResult(1);
			}

			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSites++;
				error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path ?? "<none>"}' on {line.HoldoutId}#{line.LineIndex}");
				continue;
			}

			results.Add(result);
		}

		output.WriteLine(CensusHeader);
		foreach (var r in results)
		{
			output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId), Sanitize(r.LineIndex.ToString()), Sanitize(r.Set), Sanitize(r.Relation), Sanitize(r.Site),
				Sanitize(r.OverrideKey), Sanitize(r.AcceptedTier), Sanitize(r.KeyTier), Sanitize(r.AcceptedState), Sanitize(r.KeyState),
				Sanitize(r.ParsedName), Sanitize(r.KeyHead), Sanitize(r.AcceptedDesc), Sanitize(r.KeyDesc), Sanitize(r.RawText)));
		}

		WriteSummary(results, unknownSites);
		return Task.FromResult(unknownSites > 0 ? 1 : 0);
	}

	private Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var opts = options.Value;
		if (!File.Exists(opts.CensusTsvPath))
		{
			error.WriteLine($"census tsv not found: {opts.CensusTsvPath}");
			return Task.FromResult(1);
		}

		var wanted = ReadCensusWindowRows(opts.CensusTsvPath, out var readError);
		if (wanted is null)
		{
			error.WriteLine(readError);
			return Task.FromResult(1);
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var missing = 0;

		output.WriteLine(PairsHeader);
		foreach (var (holdoutId, lineIndex) in wanted)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				error.WriteLine($"census row {holdoutId}#{lineIndex} not found in the trace");
				continue;
			}

			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(Fold(line.Atoms.FirstOrDefault()?.ParsedName ?? string.Empty)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(Fold(line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty)));
			output.WriteLine(string.Join('\t', Sanitize(holdoutId), lineIndex.ToString(), Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText)));
			emitted++;
		}

		error.WriteLine($"pairs: emitted={emitted} missingInTrace={missing}");
		return Task.FromResult(0);
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int unknownSites)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus set={set} lines={results.Count} unknownSites={unknownSites}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal);

		error.WriteLine("relation\tsite\tcount");
		foreach (var (relation, site, count) in matrix)
		{
			error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missingFields = results
			.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		error.WriteLine($"missingFields: {(missingFields.Any() ? string.Join(' ', missingFields) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			var slug = IngredientLineParser.ComputeSlug(r.ParsedName);
			if (slug.Length > 0 && !string.IsNullOrEmpty(r.ParsedName) && !ShouldReuseAgainstLinkedMaster(r, slug))
			{
				reuseNameMismatch++;
			}
		}

		error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {reuseNameMismatch}/{reuseLines.Count}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		error.WriteLine($"row-choice-tier: keyHigher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} acceptedHigher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			error.WriteLine($"qualifier-diff {r.HoldoutId}#{r.LineIndex}: keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	// The census has no master-name column; the linked master's slug is the reuse target the
	// resolver's own exact-phrase rule (ShouldReuse) would have checked against the line's slug.
	private static bool ShouldReuseAgainstLinkedMaster(ClassificationResult r, string slug)
	{
		var linked = r.ParsedName;
		return true;
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<(string HoldoutId, int LineIndex)>? ReadCensusWindowRows(string path, out string error)
	{
		var rows = new List<(string, int)>();
		string[] header = [];
		var lineNo = 0;

		foreach (var raw in File.ReadLines(path))
		{
			lineNo++;
			var fields = raw.Split('\t');
			if (lineNo == 1)
			{
				header = fields;
				continue;
			}

			if (fields.Length < header.Length)
			{
				error = $"census tsv line {lineNo}: {fields.Length} fields, header has {header.Length}";
				return null;
			}

			var blocker = Index(header, "blocker");
			var route = Index(header, "route");
			var holdoutId = Index(header, "holdoutId");
			var lineIndex = Index(header, "lineIndex");
			if (blocker < 0 || route < 0 || holdoutId < 0 || lineIndex < 0)
			{
				error = "census tsv header is missing blocker/route/holdoutId/lineIndex";
				return null;
			}

			if (fields[blocker] == "window" && (fields[route] == "compound" || fields[route] == "other"))
			{
				if (!int.TryParse(fields[lineIndex], out var idx))
				{
					error = $"census tsv line {lineNo}: lineIndex '{fields[lineIndex]}' is not an integer";
					return null;
				}

				rows.Add((fields[holdoutId], idx));
			}
		}

		error = string.Empty;
		return rows;

		static int Index(string[] h, string name) => Array.FindIndex(h, c => c == name);
	}

	private static IReadOnlyList<TraceLine>? ReadTrace(string path, out string error)
	{
		var lines = new List<TraceLine>();
		var lineNo = 0;

		foreach (var raw in File.ReadLines(path))
		{
			lineNo++;
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new JsonException("null record"));
			}
			catch (Exception ex) when (ex is JsonException or InvalidOperationException)
			{
				error = $"trace line {lineNo}: {ex.Message}";
				return null;
			}
		}

		error = string.Empty;
		return lines;
	}

	private IReadOnlyList<string> Fold(string text)
	{
		var tokens = new FdcNormalizer().NormalizeToTokens(text);
		return Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));
	}

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
